@Service
public class DSPService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public DSPService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DSPEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DSPRepository.class) );
		this.validator		= applicationContext.getBean(DSPValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		DSP
	 */
		public DSP createDSP( CreateDSPCommand command ) {

		DSP entity = new DSP();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDSPId( command.getDSPId() );
            entity.setName( command.getName() );
            entity.setWebsite( command.getWebsite() );
            entity.setRegion( command.getRegion() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of DSP {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDSPCommand
	 * @return		DSP
	 */
	public DSP updateDSP( UpdateDSPCommand command ) {

		DSP entity = new DSP();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDSPId( command.getDSPId() );
            entity.setName( command.getName() );
            entity.setWebsite( command.getWebsite() );
            entity.setRegion( command.getRegion() );
            entity.setAdAccounts( command.getAdAccounts() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of DSP {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDSPCommand
	 */
	public void delete( DeleteDSPCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDSPId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of DSP {0} ", id );

	}

	/**
	 * Method to retrieve the DSP via DSPFetchOneSummary
	 * @param 	summary DSPFetchOneSummary
	 * @return 	DSPFetchOneResponse
	 */
	public DSP getDSP( DSPFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DSPFetchOneSummary arg cannot be null" );

		DSP entity = null;
		UUID id = summary.getDSPId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a DSP using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all DSPs
	 *
	 * @return 	List<DSP>
	 */
    public List<DSP> getAllDSP() {
		List<DSP> list = projector.findAll( new FindAllDSPQuery() );
		return list;
	}


	/**
	 * add AdAccount to AdAccounts
	 * @param		command AssignAdAccountsToDSPCommand
	 */
	public void addToAdAccounts( AssignAdAccountsToDSPCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToAdAccounts(command.getDSPId(), command.getAddTo());
	}

	/**
	 * remove AdAccount from AdAccounts
	 * @param		command RemoveAdAccountsFromDSPCommand
	 */
	public void removeFromAdAccounts( RemoveAdAccountsFromDSPCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromAdAccounts(command.getDSPId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final DSPEntityProjector projector;
	private final DSPValidator validator;
	private DSP dSP 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(DSPService.class);
}
